import{_ as l,a0 as d,w as t,s as o,ao as c,I as p,x as e,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"为 Linux 用户准备的 FreeDOS 命令 | LCTT x X-CMD","titleTemplate":false,"description":"为 Linux 用户准备的 FreeDOS 命令 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为 Linux 用户准备的 FreeDOS 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为 Linux 用户准备的 FreeDOS 命令 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210603 FreeDOS commands for Linux fans","title":"为 Linux 用户准备的 FreeDOS 命令","tag":"202112","desc":""},"relativePath":"202112/20210603 FreeDOS commands for Linux fans.md","filePath":"[post].md"}'),r={name:"202112/20210603 FreeDOS commands for Linux fans.md"};function u(h,s,g,k,f,x){const n=d("Link");return t(),o("div",null,[s[15]||(s[15]=c(`<h1 id="为-linux-用户准备的-freedos-命令" tabindex="-1">为 Linux 用户准备的 FreeDOS 命令 <a class="header-anchor" href="#为-linux-用户准备的-freedos-命令" aria-label="Permalink to “为 Linux 用户准备的 FreeDOS 命令”">​</a></h1><blockquote><p>如果你已经熟悉了 Linux 命令行，尝试这些命令有助于轻松地进入 FreeDOS 。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202112/18/102331ubkem265eqz6u1mk.jpg" alt=""></p><p>如果你已经尝试过 FreeDOS ，你可能已经被命令行所吓倒。DOS 命令可能稍微不同于你所使用的 Linux 命令行，因此，使用它的命令行上需要学习一些新的命令。</p><p>但是对于 Linux 用户来说，它不是一种 “全新的” 体验。在 FreeDOS 中，除了 DOS 命令之外，我们还包含一些已经熟悉的标准的 Unix 命令。因此，如果你已经熟悉了 Linux 命令行，尝试这些命令有助于轻松地进入 FreeDOS ：</p><h3 id="在四周走走" tabindex="-1">在四周走走 <a class="header-anchor" href="#在四周走走" aria-label="Permalink to “在四周走走”">​</a></h3><p>在 FreeDOS 文件系统中使用 <code>cd</code> 命令来 <em>更改目录</em> 。在 FreeDOS 上的用法在 Linux 上的用法基本相同。要更改到一个名称为 <code>apps</code> 的子目录，输入 <code>cd apps</code> 。要回到先前的目录，输入 <code>cd ..</code> 。</p><p>在 FreeDOS 上导航浏览目录和路径是仅有的不同点，目录分隔符是 <code>\\</code>（“反斜杠”）而不是你在 Linux 上使用的 <code>/</code> （“正斜杠”）。例如，让我们假设你在 <code>\\devel</code> 目录之中，你想移动到 <code>\\fdos</code> 目录。这两个目录相对于 <em>根</em> 目录而言是处于相同的 “层次” 之中的。因此，你可以输入 <code>cd ..\\fdos</code> 来 “向后返回” 一个目录层次（使用 <code>..</code>） ，然后再 “转到” <code>fdos</code> 目录。</p><p>要更改到一个新的目录，你可以使用先前提到的反斜杠来替换需要给出的完整的路径。如果你已经深入了另外一个路径之中，并且只是像立即切换到新的位置，那么这会是非常方便的。例如，要更改到 <code>\\temp</code> 目录，你可以输入 <code>cd \\temp</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;cd apps</span></span>
<span class="line"><span>C:\\APPS&gt;cd ..</span></span>
<span class="line"><span>C:\\&gt;cd devel</span></span>
<span class="line"><span>C:\\DEVEL&gt;cd ..\\fdos</span></span>
<span class="line"><span>C:\\FDOS&gt;cd \\temp</span></span>
<span class="line"><span>C:\\TEMP&gt;_</span></span></code></pre></div><p>在 FreeDOS 中，像大多数的 DOS 系统一样，你可以在DOS 提示符中看到你的当前路径。在 Linux 上，你的提示符可能类似于 <code>$</code> 。在 FreeDOS 上，提示符会列出当前的驱动器及其当前的路径，接下来使用 <code>&gt;</code> 作为提示符（看做 Linux 上的 <code>$</code>）。</p><h3 id="列出和显示文件" tabindex="-1">列出和显示文件 <a class="header-anchor" href="#列出和显示文件" aria-label="Permalink to “列出和显示文件”">​</a></h3><p>在 Linux 上，列出当前目录中文件的标准命令是 <code>ls</code> 命令。在 FreeDOS ，它是一个不同的命令： <code>dir</code> 。但是你可以创建一个 <em>别名</em> 来获取一种与 <code>ls</code> 类似的行为。</p><p>要为另外一个命令创建一个别名，使用内置的 <code>alias</code> 命令。例如，使用此命令来为 <code>ls</code> 定义一个别名，这个别名将显示一个目录列表，与在 Linux 上使用 <code>ls</code> 类似：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;alias ls=dir /one /w /b /l</span></span>
<span class="line"><span>C:\\&gt;ls</span></span>
<span class="line"><span>[apps]    command.com   [devel]  fdauto.bat   fdconfig.sys</span></span>
<span class="line"><span>[fdos]    kernel.sys    [src]    [temp]</span></span>
<span class="line"><span>C:\\&gt;</span></span></code></pre></div><p>在 FreeDOS 上的命令选项格式与 Linux 稍微不同。在 Linux 上， 你使用一个连字符号（<code>-</code>）表示选项。但是在 FreeDOS 上，你使用一个正斜杠来表示选项。上面的 <code>alias</code> 命令使用斜杆杠字符 — 它们是 <code>dir</code> 的选项。<code>/one</code> 可选择项告诉 <code>dir</code> 以某种方式排序（<code>o</code>）：先按名称（<code>n</code>）再按扩展名（<code>e</code>）来排序一些文件和目录。<code>/w</code> 使用一个 “宽” 目录列表，<code>/b</code> 使用一种不带有 <code>dir</code> 通常提供的其它信息的 “裸” 显示，<code>/l</code> 指示 <code>dir</code> 以小写字母的形式显示文件和目录。</p><p>注意，针对于 FreeDOS 的 <code>dir</code> 命令的命令行选项与针对于 Linux 的 <code>ls</code> 命令的命令行选项截然不同，因此，你不能像你在 Linux 上一样精确地使用这个 <code>ls</code> 别名。例如，在 FreeDOS 上使用此别名输入 <code>ls -l</code> 将产生一条 “文件未找到” 的错误，因为底层的 FreeDOS 的 <code>dir</code> 命令不能找到一个名称为 <code>-l</code> 的文件。不过，对于基本的 “查看在我的系统上有哪些文件” 来说，这个 <code>ls</code> 别名已经足够帮助 Linux 用户开始使用 FreeDOS 了。</p><p>类似地，你可以为 FreeDOS 的 <code>type</code> 命令创建一个别名，来像 Linux 的 <code>cat</code> 命令一样工作。两个重新都会显示一个文本文件的内容。虽然 <code>type</code> 不支持你可能在 Linux 下使用的命令行选项，但是显示一单个文件的基本用法是相同的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\FDOS&gt;alias cat=type</span></span>
<span class="line"><span>C:\\FDOS&gt;cat version.fdi</span></span>
<span class="line"><span>PLATFORM=FreeDOS</span></span>
<span class="line"><span>VERSION=1.3-RC4</span></span>
<span class="line"><span>RELEASE=2021-04-30</span></span>
<span class="line"><span>C:\\FDOS&gt;</span></span></code></pre></div><h3 id="其它的类-unix-命令" tabindex="-1">其它的类 Unix 命令 <a class="header-anchor" href="#其它的类-unix-命令" aria-label="Permalink to “其它的类 Unix 命令”">​</a></h3><p>FreeDOS 包含一些精选的其它常见的类 Unix 命令，因此 Linux 用户将不会感觉到拘束。为在 FreeDOS 上使用这些 Linux 命令，你可能需要从 “FreeDOS Installer” - “My Package List Editor Software (FDIMPLES)” 软件包管理器来安装 “Unix Like Tools” 软件包。</p><p><img src="https://opensource.com/sites/default/files/uploads/unix-like.png" alt="Installing the Unix-like package set" title="Installing the Unix-like package set"></p><p>（Jim Hall, CC-BY SA 4.0）</p><p>并不是所有的类 Unix 实用程序都能像在 Linux 上对应的实用程序一样 <em>一致地</em> 工作。这就是我们称其为 <em>类 Unix</em> 的原因。如果你将要使用一些深层次的命令行选项，你可能需要检查其兼容性，不过，对于典型的用法是没有问题的。开始在 FreeDOS 上使用这些类 Unix 命令：</p><p><code>cal</code> 命令是标准的 Unix 的日历程序。例如，为显示当前月份的日历，只需要输入 <code>cal</code> 。为查看一个具体指定的月份，将月份和年份作为参数予以给定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;cal 6 1994</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      June 1994    </span></span>
<span class="line"><span>Su Mo Tu We Th Fr Sa</span></span>
<span class="line"><span>          1  2  3  4</span></span>
<span class="line"><span> 5  6  7  8  9 10 11</span></span>
<span class="line"><span>12 13 14 15 16 17 18</span></span>
<span class="line"><span>19 20 21 22 23 24 25</span></span>
<span class="line"><span>26 27 28 29 30</span></span></code></pre></div><p>使用 <code>du</code> 命令来查看你的磁盘使用情况。这是 Linux 的 <code>du</code> 命令的简单版本，并且不支持路径以外的任何命令行选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;du -s apps</span></span>
<span class="line"><span>usage: du (start path)</span></span>
<span class="line"><span>C:\\&gt;du apps</span></span>
<span class="line"><span>    158784 C:\\APPS\\FED</span></span>
<span class="line"><span>         0 C:\\APPS</span></span>
<span class="line"><span>Total from C:\\APPS is 158784</span></span>
<span class="line"><span>C:\\&gt;</span></span></code></pre></div><p><code>head</code> 命令显示一个文件的前几行。例如，这是一种确定一个文件是否包含正确数据的简单方法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:&gt;head fdauto.bat</span></span>
<span class="line"><span>@ECHO OFF</span></span>
<span class="line"><span>set DOSDIR=C&quot;\\FDOS</span></span>
<span class="line"><span>set LANG=EN</span></span>
<span class="line"><span>set TZ=UTC</span></span>
<span class="line"><span>set PATH=%dosdir%\\BIN</span></span>
<span class="line"><span>if exist %dosdir%\\LINKS\\NUL set PATH=%path%;%dosdir%\\LINKS</span></span>
<span class="line"><span>set NLSPATH=%dosdir%\\NLS</span></span>
<span class="line"><span>set HELPPATH=%dosdir%\\HELP</span></span>
<span class="line"><span>set TEMP=%dosdir%\\TEMP</span></span>
<span class="line"><span>set TMP=%TEMP%</span></span>
<span class="line"><span>C:\\&gt;</span></span></code></pre></div><p>要查看一个完整的文件，使用 <code>more</code> 命令，在 FreeDOS 上的默认文件查看器。这将一次显示一屏的文件，然后在显示下一屏的信息前，打印一个按下一次按键的提示。<code>more</code> 命令是一个非常简单的文件查看器；在 Linux 上你可能已经使用过一个功能更全面的查看器，可以尝试一下 <code>less</code> 命令。<code>less</code> 命令提供 “向后” 滚动一个文件的能力，以防你错过一些东西。你还可以搜索具体指定的文本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;less fdauto.bat</span></span>
<span class="line"><span>@ECHO OFF</span></span>
<span class="line"><span>set DOSDIR=C&quot;\\FDOS</span></span>
<span class="line"><span>set LANG=EN</span></span>
<span class="line"><span>set TZ=UTC</span></span>
<span class="line"><span>set PATH=%dosdir%\\BIN</span></span>
<span class="line"><span>if exist %dosdir%\\LINKS\\NUL set PATH=%path%;%dosdir%\\LINKS</span></span>
<span class="line"><span>set NLSPATH=%dosdir%\\NLS</span></span>
<span class="line"><span>set HELPPATH=%dosdir%\\HELP</span></span>
<span class="line"><span>set TEMP=%dosdir%\\TEMP</span></span>
<span class="line"><span>set TMP=%TEMP%</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>如果在你的程序路径变量（<code>PATH</code>）中有很多的目录，并且不确定某个程序是从哪里运行的，你可以使用 <code>which</code> 命令。这个命令将扫描程序路径变量，并且将打印出你正在查找的程序的完整的位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;which less</span></span>
<span class="line"><span>less    C:\\&gt;FDOS\\BIN\\LESS.EXE</span></span>
<span class="line"><span>C:\\&gt;_</span></span></code></pre></div><p>FreeDOS 1.3 RC4 包含其它的类 Unix 命令，你可能会在其它更特殊的情况下使用。这些命令包括：</p><ul><li><code>bc</code>：任意精度数字处理语言</li><li><code>sed</code>：流编辑器</li><li><code>grep</code> 和 <code>xgrep</code>：使用正则表达式搜索一个文本文件</li><li><code>md5sum</code>：生成一个文件的一个 MD5 签名</li><li><code>nro</code>：简单排版，使用 nroff 宏</li><li><code>sleep</code>：暂停系统几秒钟</li><li><code>tee</code>：保存一个命令行流的副本</li><li><code>touch</code>：修改一个文件的时间戳</li><li><code>trch</code>：转换单个字符（像 Linux 的 <code>tr</code> 一样）</li><li><code>uptime</code>：报告你 FreeDOS 系统已经运行多长的时间</li></ul><h3 id="在你控制下的-freedos" tabindex="-1">在你控制下的 FreeDOS <a class="header-anchor" href="#在你控制下的-freedos" aria-label="Permalink to “在你控制下的 FreeDOS”">​</a></h3><p>FreeDOS ，像 Linux 和 BSD 一样，是开源的。不管你是想通过学习一种新的命令行交互方式来挑战你自己，还是想再去熟悉令人舒适的类 Unix 工具，FreeDOS 都是一款有趣的值得尝鲜的操作系统。尝试一下！</p><hr>`,39)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://opensource.com/article/21/6/freedos-linux-users"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/21/6/freedos-linux-users",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[e("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(n,{href:"https://github.com/robsean"},{default:i(()=>[...s[4]||(s[4]=[e("robsean",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const L=l(r,[["render",u]]);export{S as __pageData,L as default};
